// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;

    // allow this contract (the deployer/owner) to receive ETH from withdraw()
    receive() external payable {}

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount < type(uint128).max);

        // fund C with the fuzzed amount (any party may send via fallback)
        vm.deal(address(this), amount);
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        assertTrue(address(c).balance == amount);

        // owner (this contract, the deployer) withdraws everything
        c.withdrawAll();

        // general rule: after owner withdrawAll, C retains no ether for any amount
        assertTrue(address(c).balance == 0);
    }
}
